+#include "loader.h"
+
+#include <fstream>
+
+// The key=value reader every release has used, unchanged.
+Config load_legacy_config(const std::string& aPath)
+{
+	auto file   = std::ifstream{ aPath };
+	auto config = Config{ };
+	auto line   = std::string{ };
+	while (std::getline(file, line)) {
+		if (line.empty() || line.front() == '#') {
+			continue;
+		}
+		const auto equals = line.find('=');
+		if (equals == std::string::npos) {
+			continue;
+		}
+		// A later key replaces an earlier one; values keep inner spaces.
+		config.Values[trim(line.substr(0, equals))] = trim(line.substr(equals + 1));
+	}
+	return config;
+}

