@@ -0,0 +1,42 @@
+#include "loader.h"
+
+#include <fstream>
+#include <stdexcept>
+
+struct config_error : std::runtime_error
+{
+	using std::runtime_error::runtime_error;
+};
+
+Config load_toml_config(const std::string& aPath)
+{
+	auto file    = std::ifstream{ aPath };
+	auto config  = Config{ };
+	auto table   = std::string{ };
+	auto line    = std::string{ };
+	auto number  = 0;
+	while (std::getline(file, line)) {
+		++number;
+		const auto text = trim(line);
+		if (text.empty() || text.front() == '#') {
+			continue;
+		}
+		if (text.front() == '[') {
+			if (text.back() != ']') {
+				throw config_error{ "line " + std::to_string(number) + ": a table name needs ]" };
+			}
+			table = trim(text.substr(1, text.size() - 2)) + ".";
+			continue;
+		}
+		const auto equals = text.find('=');
+		if (equals == std::string::npos) {
+			throw config_error{ "line " + std::to_string(number) + ": expected key = value" };
+		}
+		auto value = trim(text.substr(equals + 1));
+		if (value.size() >= 2 && value.front() == '"' && value.back() == '"') {
+			value = value.substr(1, value.size() - 2);
+		}
+		config.Values[table + trim(text.substr(0, equals))] = value;
+	}
+	return config;
+}

