+#include "config/loader.h"
+
+#include <cassert>
+#include <fstream>
+
+int main()
+{
+	std::ofstream{ "t.toml" } << "[window]\nwidth = 800\ntitle = \"Main view\"\n";
+	const auto config = load_toml_config("t.toml");
+	assert(config.Values.at("window.width") == "800");
+	assert(config.Values.at("window.title") == "Main view");
+	return 0;
+}
